jobs := make(chan Request, 16)          // bounded queue per dependency
for range 8 {                          // 8 workers = the bulkhead width
    go func() { for r := range jobs { callDependency(r) } }()
}

select {
case jobs <- req:                      // admitted
case <-ctx.Done():
    return ctx.Err()
default:                               // saturated: fail fast
    return errBulkheadFull
}

sem := semaphore.NewWeighted(8)                 // per-dependency permits

if !sem.TryAcquire(1) {
    return errBulkheadFull                      // fast reject on saturation
}
defer sem.Release(1)
return callDependency(ctx, req)

